    nlbticks = stead.ticks();
end

global {
    _fps = 25;
    _lists = {};
    _clones = {};
    _filter = {};
    _curloc = nil;
    push = function(listname, v)
        local list = _lists[listname];
        _lists[listname] = {next = list, value = v};
    end;
    pushObjs = function(listname, v)
        for k,vv in stead.opairs(objs(v)) do
            local o = stead.ref(vv);
            if (isObject(o)) then
                push(listname, o);
            end;
        end;
    end;
    pop = function(listname)
        local list = _lists[listname];
        if list == nil then
            return nil;
        else
            _lists[listname] = list.next;
            return list.value;
        end;
    end;
    inject = function(listname, v)
        local list = _lists[listname];
        if list == nil then
            _lists[listname] = {next = nil, value = v};
        else
            while list.next ~= nil do
                list = list.next
            end;
            list.next = {next = nil, value = v};
        end;
    end;
    eject = function(listname)
        local list = _lists[listname];
        local prevlist = list;
        local islast = true;
        if list == nil then
            return nil;
        else
            while list.next ~= nil do
                prevlist = list
                list = list.next
                islast = false
            end;
            prevlist.next = nil;
            if islast then
                _lists[listname] = nil;
            end;
            return list.value;
        end;
    end;
    rmv = function(listname, v)
        local list = _lists[listname];
        local val;
        local prevlist = nil;
        while list ~= nil do
            val = list.value;
            if (val.nlbid == v.nlbid) then
                if (prevlist == nil) then
                    _lists[listname] = list.next;
                    return;
                else
                    prevlist.next = list.next
                    return;
                end;
            end;
            prevlist = list;
            list = list.next;
        end;
    end;
    size = function(listname)
        local list = _lists[listname];
        local result = 0;
        if list == nil then
            return 0;
        else
            repeat
                list = list.next;
                result = result + 1;
            until list == nil;
        end;
        return result;
    end;
    shuffle = function(listname)
        local arr = toArray(_lists[listname]);
        _lists[listname] = nil;
        addArr(listname, shuffled(arr));
    end;
    addAll = function(s, destination, destinationList, listName, unique)
        local loclist = _lists[listName];
        if loclist == nil then
            return;
        else
            repeat
                if destination ~= nil then
                    addf(destination, loclist.value, unique);
                elseif destinationList ~= nil then
                    push(destinationList, loclist.value);
                else
                    addf(s, loclist.value, unique);
                end;
                loclist = loclist.next;
            until loclist == nil;
        end;
    end;
    shuffled = function(tab)
        local n, order, res = #tab, {}, {};
        for i=1,n do order[i] = { rand = rnd(n), idx = i } end;
        table.sort(order, function(a,b) return a.rand < b.rand end);
        for i=1,n do res[i] = tab[order[i].idx] end;
        return res;
    end;
    toArray = function(list)
        local res = {}
        local loclist = list;
        local i = 1;
        if loclist == nil then
            return nil;
        else
            repeat
                res[i] = loclist.value;
                loclist = loclist.next;
                i = i + 1;
            until loclist == nil;
        end;
        return res;
    end;
    addArr = function(listname, arr)
        local n = #arr
        for i=1,n do push(listname, arr[i]) end;
    end;
    usea = function(actionObject, targetObject)
        if actionObject ~= nil and targetObject ~= nil then
            if actionObject.usea ~= nil then
                actionObject.usea(actionObject, targetObject);
            end;
        end;
    end;
    acta = function(object)
        if object ~= nil then
            if object.acta ~= nil then
                object.acta(object);
            end;
        end;
    end;
    actf = function(object)
        if object ~= nil then
            if object.actf ~= nil then
                object.actf(object);
            end;
        end;
    end;
    clear = function(object)
        if object ~= nil then
            if object.clear ~= nil then
                object.clear(object);
            end;
        end;
    end;
    addf = function(target, object, unique)
        if target == nil then
            if not have(object) then
                take(object);
            elseif not unique then
                take(clone(object));
            end;
        else
            local ores = nil;
            if not exist(object, target) then
                ores = object;
            elseif not unique then
                ores = clone(object);
            end;
            if ores ~= nil then
                ores.container = function() return target; end;
                objs(target):add(ores);
            end;
        end;
    end;
    clrcntnr = function(coll)
        -- TODO: add implementation (set container to nil func for every obj from coll)
    end;
    revive = function()
        for k,v in pairs(_filter) do
            if v then
                local o = stead.ref(k);
                o.revive(o);
            end;
        end;
    end;
    deepcopy = function(t)
        local k; local v;
        if type(t) ~= "table" then return t end;
        local mt = getmetatable(t);
        local res = {};
        for k,v in pairs(t) do
            if type(v) == "table" and k ~= "container" then
                v = deepcopy(v)
            end;
            res[k] = v;
        end;
        setmetatable(res,mt);
        return res;
    end;
    clone = function(s)
        if s.nlbobj == "listobj" then
            return new('clonefdl(listobj, \''..s.listnam..'\')');
        else
            return new('clonef(\''..s:deref()..'\')');
        end;
    end;
    clonelst = function(s, listnam)
        if s.nlbobj == "listobj" then
            return new('clonefdl(listobj, \''..listnam..'\')');
        else
            return nil;
        end;
    end;
    clonef = function(sref)
        local s = stead.ref(sref);
        return clonefd(s);
    end;
    clonefd = function(s)
        local ret = deepcopy(s);
        local r = _clones[s.nlbid];
        if r == nil then
            r = 1;
        else
            r = r + 1;
        end;
        _clones[s.nlbid] = r;
        ret.nam = s.nam..r;
        return ret;
    end;
    clonefdl = function(s, listnam)
        local ret = clonefd(s)
        ret.listnam = listnam;
        return ret;
    end;
    curloc = function()
        if _curloc == nil then
            return here();
        else
            return _curloc;
        end;
    end;
    nlbwalk = function(s, loc)
        if (s ~= loc) then
            _curloc = loc;
            walk(loc);
            if _curloc.wastext then loc.wastext = true; end;
        else
            local lasttext = s.lasttext;
            local wastext = s.wastext;
            if s.exit ~= nil then
                s.exit(s, s);
            end
            if s.enter ~= nil then
                s.enter(s, s);
            end
            s.wastext = wastext;
            s.lasttext = lasttext;
        end
    end;
}

listobj = {
    nam = "listobj",
    nlbobj = "listobj",
    nlbid = "listobj",
    deref = function(s) return stead.deref(listobj); end,
    listnam = "",
    clear = function(s)
        local r = eject(s.listnam);
        while r ~= nil do
            r = eject(s.listnam);
        end;
    end,
    act = function(s)
        s.acta(s)
        local loc = curloc();
        loc.autos(loc);
    end,
    acta = function(s)
        s.actf(s)
    end,
    actf = function(s)
        local list = _lists[s.listnam];
        if list ~= nil then
            repeat
                list.value.acta(list.value);
                list = list.next;
            until list == nil;
        end;
    end,
    use = function(s, w)
        s.usea(s, w, w);
        local loc = curloc();
        loc.autos(loc);
    end,
    usea = function(s, w, ww)
        s.usef(s, w, ww);
    end,
    usef = function(s, w, ww)
        local list = _lists[s.listnam];
        if list ~= nil then
            repeat
                list.value.usea(list.value, w, ww);
                list = list.next;
            until list == nil;
        end;
    end,
    used = function(s, w)
        s.useda(s, w);
        local loc = curloc();
        loc.autos(loc);
    end,
    useda = function(s, w)
        s.usedf(s, w);
    end,
    usedf = function(s, w)
        local list = _lists[s.listnam];
        if list ~= nil then
            repeat
                w.usea(w, list.value, list.value);
                list = list.next;
            until list == nil;
        end;
    end;
}
